    15  bool OpenTypeLOCA::Parse(const uint8_t *data, size_t length) {
    16    Buffer table(data, length);
    17
    18    // We can't do anything useful in validating this data except to ensure that
    19    // the values are monotonically increasing.
    20
    21    OpenTypeMAXP *maxp = dynamic_cast<OpenTypeMAXP*>(
    22        GetFont()->GetTable(OTS_TAG_MAXP));
    23    OpenTypeHEAD *head = dynamic_cast<OpenTypeHEAD*>(
    24        GetFont()->GetTable(OTS_TAG_HEAD));
    25    if (!maxp || !head) {
    26      return Error("maxp or head tables missing from font, needed by loca");
    27    }
    28
    29    const unsigned num_glyphs = maxp->num_glyphs;
    30    unsigned last_offset = 0;
    31    this->offsets.resize(num_glyphs + 1);
    32    // maxp->num_glyphs is uint16_t, thus the addition never overflows.
    33
    34    if (head->index_to_loc_format == 0) {
    35      // Note that the <= here (and below) is correct. There is one more offset
    36      // than the number of glyphs in order to give the length of the final
    37      // glyph.
    38      for (unsigned i = 0; i <= num_glyphs; ++i) {
    39        uint16_t offset = 0;
    40        if (!table.ReadU16(&offset)) {
    41          return Error("Failed to read offset for glyph %d", i);
    42        }
    43        if (offset < last_offset) {
    44          return Error("Out of order offset %d < %d for glyph %d", offset, last_offset, i);
    45        }
    46        last_offset = offset;
    47        this->offsets[i] = offset * 2;
    48      }
    49    } else {
    50      for (unsigned i = 0; i <= num_glyphs; ++i) {
    51        uint32_t offset = 0;
    52        if (!table.ReadU32(&offset)) {
    53          return Error("Failed to read offset for glyph %d", i);
    54        }
    55        if (offset < last_offset) {
    56          return Error("Out of order offset %d < %d for glyph %d", offset, last_offset, i);
    57        }
    58        last_offset = offset;
    59        this->offsets[i] = offset;
    60      }
    61    }
    62
    63    return true;
    64  }
