    24                                              uint32_t *xy_coordinates_length) {
    25    uint8_t flag = 0;
    26    if (!table->ReadU8(&flag)) {
    27      return Error("Can't read flag");
    28    }
    29
    30    uint32_t delta = 0;
    31    if (flag & (1u << 1)) {  // x-Short
    32      ++delta;
    33    } else if (!(flag & (1u << 4))) {
    34      delta += 2;
    35    }
    36
    37    if (flag & (1u << 2)) {  // y-Short
    38      ++delta;
    39    } else if (!(flag & (1u << 5))) {
    40      delta += 2;
    41    }
    42
    43    if (flag & (1u << 3)) {  // repeat
    44      if (*flags_count_logical + 1 >= num_flags) {
    45        return Error("Count too high (%d + 1 >= %d)", *flags_count_logical, num_flags);
    46      }
    47      uint8_t repeat = 0;
    48      if (!table->ReadU8(&repeat)) {
    49        return Error("Can't read repeat value");
    50      }
    51      if (repeat == 0) {
    52        return Error("Zero repeat");
    53      }
    54      delta += (delta * repeat);
    55
    56      *flags_count_logical += repeat;
    57      if (*flags_count_logical >= num_flags) {
    58        return Error("Count too high (%d >= %d)", *flags_count_logical, num_flags);
    59      }
    60      ++(*flags_count_physical);
    61    }
    62
    63    if ((flag & (1u << 6)) || (flag & (1u << 7))) {  // reserved flags
    64      return Error("Bad glyph flag value (%d), reserved flags must be set to zero", flag);
    65    }
    66
    67    *xy_coordinates_length += delta;
    68    if (gly_length < *xy_coordinates_length) {
    69      return Error("Glyph coordinates length too low (%d < %d)", gly_length, *xy_coordinates_length);
    70    }
    71
    72    return true;
    73  }
    74
    75  bool OpenTypeGLYF::ParseSimpleGlyph(const uint8_t *data,
    76                                      ots::Buffer *table,
    77                                      int16_t num_contours,
    78                                      uint32_t gly_offset,
    79                                      uint32_t gly_length,
    80                                      uint32_t *new_size) {
    81    // read the end-points array
    82    uint16_t num_flags = 0;
    83    for (int i = 0; i < num_contours; ++i) {
    84      uint16_t tmp_index = 0;
    85      if (!table->ReadU16(&tmp_index)) {
    86        return Error("Can't read contour index %d", i);
    87      }
    88      if (tmp_index == 0xffffu) {
    89        return Error("Bad contour index %d", i);
    90      }
    91      // check if the indices are monotonically increasing
    92      if (i && (tmp_index + 1 <= num_flags)) {
    93        return Error("Decreasing contour index %d + 1 <= %d", tmp_index, num_flags);
    94      }
    95      num_flags = tmp_index + 1;
    96    }
    97
    98    uint16_t bytecode_length = 0;
    99    if (!table->ReadU16(&bytecode_length)) {
   100      return Error("Can't read bytecode length");
   101    }
   102
   103    OpenTypeMAXP *maxp = dynamic_cast<OpenTypeMAXP*>(
   104        GetFont()->GetTable(OTS_TAG_MAXP));
   105    if (!maxp) {
   106      return Error("Required maxp table missing");
   107    }
   108    if (maxp->version_1 &&
   109        (maxp->max_size_glyf_instructions < bytecode_length)) {
   110      return Error("Bytecode length too high %d", bytecode_length);
   111    }
   112
   113    const uint32_t gly_header_length = 10 + num_contours * 2 + 2;
   114    if (gly_length < (gly_header_length + bytecode_length)) {
   115      return Error("Glyph header length too high %d", gly_header_length);
   116    }
   117
   118    this->iov.push_back(std::make_pair(
   119        data + gly_offset,
   120        static_cast<size_t>(gly_header_length + bytecode_length)));
